def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_op = opp[-1]
    last_me = me[-1]

    opp_c = 0
    for x in opp:
        if x == 'C':
            opp_c += 1
    opp_d = n - opp_c

    # Opening: cooperate.
    if n < 5:
        return 'C'

    # Long-run extreme defector detection.
    if n >= 12 and opp_d >= n - 2:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Opponent just defected: retaliate, but allow controlled recovery.
    if last_op == 'D':
        streak = 0
        for x in reversed(opp):
            if x == 'D':
                streak += 1
            else:
                break
        if streak >= 4:
            if rng.random() < 0.08:
                return 'C'
            return 'D'
        if last_me == 'C':
            return 'D'
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent cooperated. Estimate recent behavior.
    w = n if n < 12 else 12
    recent = opp[-w:]
    recent_c = 0
    for x in recent:
        if x == 'C':
            recent_c += 1
    recent_rate = recent_c / float(w)

    long_w = n if n < 30 else 30
    long_c = 0
    for x in opp[-long_w:]:
        if x == 'C':
            long_c += 1
    long_rate = long_c / float(long_w)

    # Near end, exploit a forgiving/cooperative opponent for extra points.
    remaining = 100 - n
    if remaining <= 8 and long_rate > 0.75:
        if rng.random() < 0.7:
            return 'D'
        return 'C'
    if remaining <= 4 and long_rate > 0.55:
        return 'D'

    # Strong recent defection despite last C: stay defensive.
    if recent_rate < 0.35:
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Mostly cooperative opponent: keep cooperation, rare probing.
    if recent_rate >= 0.8:
        if n >= 15 and long_rate > 0.85 and rng.random() < 0.04:
            return 'D'
        return 'C'

    # Mixed opponent: reciprocal with occasional forgiveness.
    if last_me == 'D':
        return 'C'
    if recent_rate >= 0.6:
        return 'C'
    if rng.random() < 0.5:
        return 'C'
    return 'D'
